changeSet.sql:
CREATE TABLE nexus.tuple_deliveries (
    tenant_id      TEXT        NOT NULL,
    subspace       TEXT        NOT NULL,
    subscriber     TEXT        NOT NULL,
    tuple_id       BYTEA       NOT NULL,
    announced_at   TIMESTAMPTZ NOT NULL,
    announce_count INTEGER     NOT NULL DEFAULT 1,
    CONSTRAINT tuple_deliveries_pk PRIMARY KEY (tenant_id, subspace, subscriber, tuple_id),
    CONSTRAINT tuple_deliveries_tuple_fk FOREIGN KEY (tuple_id)
        REFERENCES nexus.tuples (id) ON DELETE CASCADE
) WITH (autovacuum_vacuum_scale_factor = 0.01);

CREATE INDEX idx_tuple_deliveries_tuple_id ON nexus.tuple_deliveries (tuple_id);

ALTER TABLE nexus.tuple_deliveries ENABLE ROW LEVEL SECURITY;
ALTER TABLE nexus.tuple_deliveries FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON nexus.tuple_deliveries
    USING      (tenant_id = current_setting('nexus.tenant', true))
    WITH CHECK (tenant_id = current_setting('nexus.tenant', true));

rollback.sql:
DROP POLICY IF EXISTS tenant_isolation ON nexus.tuple_deliveries;
ALTER TABLE nexus.tuple_deliveries NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.tuple_deliveries DISABLE ROW LEVEL SECURITY;
DROP INDEX IF EXISTS nexus.idx_tuple_deliveries_tuple_id;
DROP TABLE IF EXISTS nexus.tuple_deliveries;
